package br.com.bemdoar.controller;
import br.com.bemdoar.dto.*;import br.com.bemdoar.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/oportunidades")public class OportunidadeController{private final OportunidadeService s;public OportunidadeController(OportunidadeService s){this.s=s;}@GetMapping public List<OportunidadeResponse> listar(){return s.listar();}@GetMapping("/{id}")public OportunidadeResponse buscar(@PathVariable Long id){return s.buscar(id);}@PostMapping @PreAuthorize("hasRole('ADMINISTRADOR')")public ResponseEntity<OportunidadeResponse> criar(@Valid @RequestBody OportunidadeRequest q){return ResponseEntity.status(201).body(s.criar(q));}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public OportunidadeResponse editar(@PathVariable Long id,@Valid @RequestBody OportunidadeRequest q){return s.editar(id,q);}@PatchMapping("/{id}/abrir")@PreAuthorize("hasRole('ADMINISTRADOR')")public OportunidadeResponse abrir(@PathVariable Long id){return s.abrir(id);}@PatchMapping("/{id}/encerrar")@PreAuthorize("hasRole('ADMINISTRADOR')")public OportunidadeResponse encerrar(@PathVariable Long id){return s.encerrar(id);}}
